u PRP, por paciente/procedimento (sem aplicação). Produção de plasma gel + locação de equipamento: R$ 250,00. Produto disponível dentro da Grande São Paulo.","duracao":45,"valor":35000,"exige":true,"tipo":"Centrífuga PRF","unidade":"PACIENTE","permite":false,"rotulo":null,"minima":1,"incluida":null,"adicional":0,"ufs":["AC","AL","AP","AM","BA","CE","DF","ES","GO","MA","MT","MS","MG","PA","PB","PR","PE","PI","RJ","RN","RS","RO","RR","SC","SE","TO"]},{"nome":"PRF para Medicina","nomes":["PRF para Medicina"],"familia":"PRF – Coleta e Produção","categoria":"SAUDE","descricao":"Produção de membranas, PRP, PRF em fase líquida e manipulação de PRF Block. Atuação em consultórios e hospitais.","duracao":45,"valor":70000,"exige":true,"tipo":"Centrífuga PRF","unidade":"PACIENTE","permite":false,"rotulo":null,"minima":1,"incluida":null,"adicional":0,"ufs":[]},{"nome":"I-PRF Day","nomes":["I-PRF Day"],"familia":"PRF – Coleta e Produção","categoria":"SAUDE","descricao":"Produção de I-PRF, I-PRF+, S-PRF ou PRP por 4 horas, até 6 pessoas (sem aplicação). Produção de plasma gel + locação de equipamento: R$ 250,00. Valor para um raio de 150 km da cidade de São Paulo.","duracao":240,"valor":75000,"exige":true,"tipo":"Centrífuga PRF","unidade":"PERIODO","permite":false,"rotulo":null,"minima":1,"incluida":null,"adicional":0,"ufs":["AC","AL","AP","AM","BA","CE","DF","ES","GO","MA","MT","MS","MG","PA","PB","PR","PE","PI","RJ","RN","RS","RO","RR","SC","SE","TO"]}]$json$::jsonb) LOOP
    UPDATE "Servico" SET
      "nome" = r->>'nome',
      "familia" = r->>'familia',
      "categoria" = (r->>'categoria')::"CategoriaServico",
      "descricao" = r->>'descricao',
      "duracaoMin" = (r->>'duracao')::int,
      "valorPadraoCentavos" = (r->>'valor')::int,
      "exigeEquipamento" = (r->>'exige')::boolean,
      "tipoEquipamento" = r->>'tipo',
      "unidadeCobranca" = (r->>'unidade')::"UnidadeCobranca",
      "permiteQuantidade" = (r->>'permite')::boolean,
      "rotuloQuantidade" = r->>'rotulo',
      "quantidadeMinima" = (r->>'minima')::int,
      "quantidadeIncluida" = (r->>'incluida')::int,
      "valorAdicionalCentavos" = (r->>'adicional')::int,
      "ufsIndisponiveis" = ARRAY(SELECT jsonb_array_elements_text(r->'ufs')),
      "ativo" = true, "desativadoEm" = NULL, "atualizadoEm" = NOW()
    WHERE "id" = (
      SELECT "id" FROM "Servico"
      WHERE "nome" = ANY(ARRAY(SELECT jsonb_array_elements_text(r->'nomes')))
      ORDER BY ("nome" = r->>'nome') DESC, "criadoEm" LIMIT 1
    );

    IF NOT FOUND THEN
      INSERT INTO "Servico" (
        "id", "nome", "familia", "categoria", "descricao", "duracaoMin", "valorPadraoCentavos",
        "exigeEquipamento", "tipoEquipamento", "unidadeCobranca", "permiteQuantidade", "rotuloQuantidade",
        "quantidadeMinima", "quantidadeIncluida", "valorAdicionalCentavos", "ufsIndisponiveis",
        "ativo", "criadoEm", "atualizadoEm"
      ) VALUES (
        gen_random_uuid()::text, r->>'nome', r->>'familia', (r->>'categoria')::"CategoriaServico", r->>'descricao',
        (r->>'duracao')::int, (r->>'valor')::int, (r->>'exige')::boolean, r->>'tipo',
        (r->>'unidade')::"UnidadeCobranca", (r->>'permite')::boolean, r->>'rotulo',
        (r->>'minima')::int, (r->>'incluida')::int, (r->>'adicional')::int,
        ARRAY(SELECT jsonb_array_elements_text(r->'ufs')), true, NOW(), NOW()
      );
    END IF;
  END LOOP;

  -- Saiu do catálogo atual: desativado, nunca apagado (pedidos antigos apontam para ele).
  UPDATE "Servico" SET "ativo" = false, "desativadoEm" = NOW(), "atualizadoEm" = NOW()
   WHERE "nome" = ANY(ARRAY(SELECT jsonb_array_elements_text($json$["PRF – Coleta e Produção de Concentrados Plaquetários"]$json$::jsonb))) AND "ativo";
END
$catalogo$;
